import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Caffeine, CaffeineLease, CaffeineMode } from '../types'
import { IDLE, describe, isLow, parsePower, wantAwake } from './hold'
import type { Power } from './hold'

/** Each caffeinate lapses on its own after this long, so a crashed session never keeps the Mac up. */
const LEASE_S = 600
/** Renewed at half its life while still wanted. */
const RENEW_MS = 5 * 60_000
const TICK_MS = 15_000
const POWER_EVERY_MS = 60_000
const MODES: readonly string[] = ['auto', 'on', 'off']

const caffeine = atom({ plugin: 'caffeinate', key: 'caffeine' } as const, IDLE)
const lease = atom({ plugin: 'caffeinate', key: 'lease' } as const, null)

// What the session is doing, as the turn and stop hooks see it. A reload
// forgets these and finds the session idle until its next turn; the lease is
// the host's, so the caffeinate it names is still renewed or ended.
let turnSince: number | null = null
let background = 0
let backgroundAt = 0
let isEnding = false
let power: Power = { source: 'unknown', battery: null }
let powerAt = 0
let chain: Promise<void> = Promise.resolve()

function loopOf(e: object): string | undefined {
  const { agentId } = e as { agentId?: unknown }

  return typeof agentId === 'string' ? agentId : undefined
}

async function startLease($: EngineInterface): Promise<CaffeineLease> {
  // Detached, its output thrown away, so the call returns at once with its pid.
  const { stdout } = await $.process.run([
    '/bin/sh',
    '-c',
    `/usr/bin/caffeinate -i -t ${LEASE_S} </dev/null >/dev/null 2>&1 & echo $!`,
  ])
  const pid = Number.parseInt(stdout.trim(), 10)

  return Number.isInteger(pid) && pid > 0 ? { pid, startedAt: await $.clock.now() } : null
}

async function endLease($: EngineInterface, held: CaffeineLease): Promise<void> {
  if (!held) return
  // Only while that pid is still a caffeinate: once one lapses its pid can be reused.
  await $.process.run([
    '/bin/sh',
    '-c',
    'ps -p "$1" -o comm= | grep -q caffeinate && kill "$1"; true',
    'caffeinate-end',
    String(held.pid),
  ])
}

async function readPower($: EngineInterface, now: number): Promise<Power> {
  if (now - powerAt < POWER_EVERY_MS) return power
  const { stdout } = await $.process.run(['/usr/bin/pmset', '-g', 'batt'])
  power = parsePower(stdout)
  powerAt = now

  return power
}

async function sync($: EngineInterface): Promise<void> {
  const now = await $.clock.now()
  const was = await read($, caffeine)
  const why = isEnding ? null : wantAwake({ mode: was.mode, turnSince, background, backgroundAt, now })
  const supply = why === null ? power : await readPower($, now)
  const isHeldBack = why !== null && isLow(supply)
  const isWanted = why !== null && !isHeldBack

  let held = await read($, lease)
  if (isWanted && (held === null || now - held.startedAt >= RENEW_MS)) {
    // The new one first, so the Mac is never left unheld between the two.
    const fresh = await startLease($)
    await endLease($, held)
    held = fresh
    await update($, lease, () => fresh)
  } else if (!isWanted && held !== null) {
    await endLease($, held)
    held = null
    await update($, lease, () => null)
  }

  const isAwake = isWanted && held !== null
  const since = isAwake ? (was.isAwake ? was.since : now) : 0
  const next: Caffeine = {
    mode: was.mode,
    isAwake,
    reason: isAwake ? why : null,
    since,
    minutes: isAwake ? Math.floor((now - since) / 60_000) : 0,
    source: supply.source,
    battery: supply.battery,
    isHeldBack,
  }
  if (isHeldBack && !was.isHeldBack) {
    $.ui.toast(`☕ Battery at ${supply.battery}%: letting the Mac sleep until it is on charge`)
  }
  // Written only when what a reader draws changed: once a minute while held, never while idle.
  if (JSON.stringify(next) !== JSON.stringify(was)) await update($, caffeine, held => ({ ...next, mode: held.mode }))
}

// Changes run one at a time, so a tick and a turn's end landing together
// cannot both start a caffeinate.
function refresh($: EngineInterface, change?: (held: Caffeine) => Caffeine): Promise<void> {
  chain = chain
    .then(async () => {
      if (change) await update($, caffeine, change)
      await sync($)
    })
    .catch(error => $.ui.log(`caffeinate: ${String(error)}`, { to: 'debug' }))

  return chain
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const started = await next(e)
    isEnding = false
    await $.command.register({
      name: 'caffeinate',
      description: 'Keep the Mac awake while Claude works: on, off, auto, or show what it is doing',
      argumentHint: '[on|off|auto]',
    })
    $.clock.every(TICK_MS, () => void refresh($))
    void refresh($)

    return started
  })

  on('turn.start', async ($, e, next) => {
    if (loopOf(e) === undefined && turnSince === null) turnSince = await $.clock.now()

    return next(e)
  })

  // Each turn's end says what background work is still in flight; that work
  // wakes the session with a turn of its own when it finishes, which recounts.
  on('classic.Stop', async ($, e, next) => {
    const answered = await next(e)
    if (e.agent_id === undefined) {
      background = e.background_tasks?.length ?? 0
      backgroundAt = await $.clock.now()
      await refresh($)
    }

    return answered
  }).catch(($, e, next) => next(e))

  on('turn.complete', async ($, e, next) => {
    const done = await next(e)
    if (loopOf(e) !== undefined) return done
    turnSince = null
    await refresh($)

    return done
  })

  // A /clear starts the watch over and keeps the mode; leaving the session lets go now
  // rather than when the lease lapses.
  on('session.end', async ($, e, next) => {
    const ended = await next(e)
    turnSince = null
    background = 0
    isEnding = e.reason !== 'clear'
    await refresh($)

    return ended
  })

  on('command.run', { command: 'caffeinate' }, async ($, e) => {
    const asked = e.args.trim().toLowerCase()
    if (asked !== '' && !MODES.includes(asked)) return { text: 'Usage: /caffeinate [on|off|auto]' }
    const mode = asked as CaffeineMode
    await refresh($, asked === '' ? undefined : held => ({ ...held, mode }))

    return { text: describe(await read($, caffeine)) }
  })
}

