import type { Caffeine, CaffeineMode, CaffeineReason, CaffeineSource } from '../types'

/** A turn counts as long once it has run this long; shorter ones never hold the Mac. */
export const GRACE_MS = 60_000
/** On battery at or below this charge the hold is let go, and taken again on charge. */
export const LOW_BATTERY = 20
/**
 * Background work reports back with a turn of its own when it ends, and each
 * turn's end recounts it. A count no turn has refreshed in this long is stale
 * (work stopped with no turn after it), and the hold it asked for lapses.
 */
export const BACKGROUND_MAX_MS = 12 * 60 * 60_000

export const IDLE: Caffeine = {
  mode: 'auto',
  isAwake: false,
  reason: null,
  since: 0,
  minutes: 0,
  source: 'unknown',
  battery: null,
  isHeldBack: false,
}

export type Power = { source: CaffeineSource; battery: number | null }

/** What the session is doing, as the turn and stop hooks have seen it. */
export type Watch = {
  mode: CaffeineMode
  turnSince: number | null
  background: number
  backgroundAt: number
  now: number
}

/** Reads `pmset -g batt`: the power source, and the charge where there is a battery. */
export function parsePower(out: string): Power {
  const source = out.includes("'AC Power'") ? 'ac' : out.includes("'Battery Power'") ? 'battery' : 'unknown'
  const charge = /(\d{1,3})%;/.exec(out)

  return { source, battery: charge ? Number(charge[1]) : null }
}

/** Why the Mac should be held awake now, or null to let it sleep as it normally would. */
export function wantAwake(watch: Watch): CaffeineReason | null {
  if (watch.mode === 'off') return null
  if (watch.mode === 'on') return 'manual'
  if (watch.turnSince !== null && watch.now - watch.turnSince >= GRACE_MS) return 'turn'
  if (watch.background > 0 && watch.now - watch.backgroundAt < BACKGROUND_MAX_MS) return 'background'

  return null
}

export function isLow(power: Power): boolean {
  return power.source === 'battery' && power.battery !== null && power.battery <= LOW_BATTERY
}

/** `7` → `7m`, `72` → `1h12m`. */
export function elapsed(minutes: number): string {
  if (minutes < 1) return '<1m'
  if (minutes < 60) return `${minutes}m`

  return `${Math.floor(minutes / 60)}h${String(minutes % 60).padStart(2, '0')}m`
}

const FOR: Record<CaffeineReason, string> = {
  turn: 'while Claude works on this turn',
  background: 'while background work from this session finishes',
  manual: 'until you run /caffeinate auto or /caffeinate off',
}

const LID = 'The display can still sleep and lock; closing the lid still puts the Mac to sleep.'

/** What `/caffeinate` answers. */
export function describe(caffeine: Caffeine): string {
  if (caffeine.mode === 'off') return 'Off for this session: the Mac sleeps as it normally would. /caffeinate auto turns it back on.'
  if (caffeine.isHeldBack) return `On battery at ${caffeine.battery}%: letting the Mac sleep until it is on charge.`
  if (caffeine.isAwake && caffeine.reason) {
    return `Keeping the Mac awake ${FOR[caffeine.reason]} (${elapsed(caffeine.minutes)} so far). ${LID}`
  }

  return `Standing by: the Mac is held awake once a turn has run a minute, and while background work runs. ${LID}`
}

