/** How the session keeps the Mac awake: by what Claude is doing, always, or never. */
export type CaffeineMode = 'auto' | 'on' | 'off'

/**
 * What the Mac is held awake for: a turn that has run past a minute, background
 * work the session left running when its turn ended, or `/caffeinate on`.
 */
export type CaffeineReason = 'turn' | 'background' | 'manual'

/** Where the Mac draws its power from, as `pmset -g batt` says. */
export type CaffeineSource = 'ac' | 'battery' | 'unknown'

/** The hold as other mods draw it: Sprout's coffee cup reads this. */
export type Caffeine = {
  mode: CaffeineMode
  /** A caffeinate assertion is held now. */
  isAwake: boolean
  reason: CaffeineReason | null
  /** When the current hold began, in ms since the epoch; 0 while none is held. */
  since: number
  /** Whole minutes held, so a reader redraws once a minute and no more often. */
  minutes: number
  source: CaffeineSource
  /** Battery charge in percent; null on a Mac with no battery. */
  battery: number | null
  /** The hold was let go because the battery is low; it is taken again on charge. */
  isHeldBack: boolean
}

/** The caffeinate process this session started, kept by the host so a reload can still end it. */
export type CaffeineLease = { pid: number; startedAt: number } | null

declare module 'claude-code' {
  interface PluginState {
    caffeinate: { caffeine: Caffeine; lease: CaffeineLease }
  }
}
